#pragma once
#include "Processor.h"
#include <NexumDesign.h>
#include <iostream>
namespace noctrl {
inline int suitEditorCheck(SynthProcessor& processor,const juce::String& product){using namespace juce;if(SystemStats::getEnvironmentVariable("NEXUM_DESIGN_FILE",{}).isEmpty())return 90;ScopedJuceInitialiser_GUI gui;auto old=nd::Store::instance().get().clone();auto doc=nd::emptyDocument();doc["rules"]["global"]["values"].getDynamicObject()->setProperty("color.canvas","ff4e2549");doc["rules"]["global"]["values"].getDynamicObject()->setProperty("color.accent","ff8de09b");int failed=0;auto run=[&](SynthProcessor& p,const String& name){p.prepareToPlay(48000,512);nd::Store::instance().preview(nd::emptyDocument());std::unique_ptr<AudioProcessorEditor> editor(p.createEditor());auto parameters=p.state.copyState();auto before=editor->createComponentSnapshot(editor->getLocalBounds());editor->addToDesktop(0);editor->setVisible(false);auto result=nd::Store::save(doc);Thread::sleep(550);Timer::callPendingTimersSynchronously();auto after=editor->createComponentSnapshot(editor->getLocalBounds());if(result.failed()||before.getPixelAt(2,2)==after.getPixelAt(2,2)||after.getPixelAt(2,2).getARGB()!=0xff4e2549||editor->getLookAndFeel().findColour(Slider::thumbColourId).getARGB()!=0xff8de09b||!parameters.isEquivalentTo(p.state.copyState())){std::cerr<<"FAIL suit live style "<<name<<" pixel "<<after.getPixelAt(2,2).toString()<<"\n";++failed;}auto file=File::getCurrentWorkingDirectory().getChildFile("Reports/suit-"+name+".png");FileOutputStream out(file);out.setPosition(0);out.truncate();PNGImageFormat().writeImageToStream(after,out);editor->removeFromDesktop();};run(processor,product);nd::designFile().deleteFile();nd::Store::instance().preview(old);std::cout<<(failed?"FAIL":"PASS")<<": real product editor, shared file, live timer refresh, original colour fallback, canonical look-and-feel refresh and unchanged parameter states\n";return failed;}
inline int suitStyleChecks(){auto owner=std::make_unique<SynthProcessor>();return suitEditorCheck(*owner,"synth");}
}
